<?php
declare(strict_types=1);$c=$user['company_id'];$selectedProject=(string)($_GET['project']??($projects[0]['id']??''));if($selectedProject&&!scoped_project($db,$user,$selectedProject))$selectedProject=(string)($projects[0]['id']??'');$units=phase_rows($db,'SELECT * FROM units WHERE company_id=? AND project_id=? ORDER BY tower,wing,floor_label,unit_number',[$c,$selectedProject]);$customers=phase_rows($db,'SELECT * FROM customers WHERE company_id=? ORDER BY created_at DESC',[$c]);$brokers=phase_rows($db,'SELECT b.*,COALESCE(SUM(bc.amount_earned),0) earned,COALESCE(SUM(bc.amount_paid),0) paid FROM brokers b LEFT JOIN broker_commissions bc ON bc.broker_id=b.id WHERE b.company_id=? GROUP BY b.id ORDER BY b.name',[$c]);$bookings=phase_rows($db,'SELECT b.*,u.unit_number,u.tower,c.name customer_name,c.phone customer_phone,p.name project_name,br.name broker_name FROM bookings b JOIN units u ON u.id=b.unit_id JOIN customers c ON c.id=b.customer_id JOIN projects p ON p.id=b.project_id LEFT JOIN brokers br ON br.id=b.broker_id WHERE b.company_id=? ORDER BY b.created_at DESC',[$c]);$schedules=phase_rows($db,'SELECT s.*,b.project_id,u.unit_number,c.name customer_name FROM payment_schedules s JOIN bookings b ON b.id=s.booking_id JOIN units u ON u.id=b.unit_id JOIN customers c ON c.id=b.customer_id WHERE s.company_id=? ORDER BY s.due_date',[$c]);$totalDue=array_sum(array_column($schedules,'amount_due'));$totalReceived=array_sum(array_column($schedules,'amount_received'));function p4h(string $a,string $page,string $project):string{return phase_hidden('', $page,$project).'<input type="hidden" name="phase4_action" value="'.e($a).'">';}
?>
<section class="page-title"><div><span class="eyebrow">PROPERTY SALES</span><h1><?=e(match($page){'units'=>'Unit inventory','bookings'=>'Customers & bookings','collections'=>'Collections','brokers'=>'Brokers & commissions',default=>'Property sales'})?></h1><p class="muted">Manage availability, bookings and receivables against each project.</p></div><form method="get" class="project-filter"><input type="hidden" name="page" value="<?=e($page)?>"><select name="project" onchange="this.form.submit()"><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=$p['id']===$selectedProject?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></section>
<?php if($page==='units'):?><section class="cards"><article class="card"><span>Total units</span><strong><?=count($units)?></strong></article><article class="card"><span>Available</span><strong><?=count(array_filter($units,fn($u)=>$u['status']==='available'))?></strong></article><article class="card"><span>Booked</span><strong><?=count(array_filter($units,fn($u)=>$u['status']==='booked'))?></strong></article><article class="card"><span>Inventory value</span><strong><?=inr(array_sum(array_column($units,'final_price')))?></strong></article></section><form class="form-card wide" method="post"><h2>Add property unit</h2><?=p4h('unit_add','units',$selectedProject)?><div class="form-grid"><label class="field">Tower<input name="tower"></label><label class="field">Wing<input name="wing"></label><label class="field">Floor<input name="floor_label"></label><label class="field">Unit number<input name="unit_number" required></label><label class="field">Property type<select name="property_type"><?php foreach(['1BHK','2BHK','3BHK','Office','Shop','Other'] as $x):?><option><?=$x?></option><?php endforeach;?></select></label><label class="field">Carpet area<input type="number" step=".01" name="carpet_area"></label><label class="field">Built-up area<input type="number" step=".01" name="builtup_area"></label><label class="field">Base price<input type="number" step=".01" name="base_price"></label><label class="field">Floor rise<input type="number" step=".01" name="floor_rise"></label><label class="field">Parking<input type="number" step=".01" name="parking_charges"></label><label class="field">Other charges<input type="number" step=".01" name="other_charges"></label><label class="field">Status<select name="status"><?php foreach(['available','hold','reserved','blocked'] as $x):?><option><?=$x?></option><?php endforeach;?></select></label></div><button class="button">Add unit</button></form><section class="unit-grid"><?php foreach($units as $u):?><article class="unit-card <?=$u['status']?>"><div><small><?=e(trim($u['tower'].' '.$u['wing'].' · Floor '.$u['floor_label']))?></small><h3><?=e($u['unit_number'])?></h3><p><?=e($u['property_type'])?> · <?=e($u['carpet_area'])?> sq ft</p><b><?=inr($u['final_price'])?></b></div><span class="pill"><?=e($u['status'])?></span><?php if(!in_array($u['status'],['booked','sold'],true)):?><form method="post"><?=p4h('unit_status','units',$selectedProject)?><input type="hidden" name="unit_id" value="<?=e($u['id'])?>"><select name="status"><?php foreach(['available','hold','reserved','blocked','cancelled'] as $x):?><option <?=$u['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Update</button></form><?php endif;?></article><?php endforeach;?></section>
<?php elseif($page==='bookings'):?><div class="split"><form class="form-card" method="post"><h2>Add customer</h2><?=p4h('customer_add','bookings',$selectedProject)?><label class="field">Linked lead<select name="lead_id"><option value="">Not linked</option><?php foreach($leads as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach;?></select></label><label class="field">Name<input name="name" required></label><label class="field">Phone<input name="phone"></label><label class="field">Email<input type="email" name="email"></label><label class="field">Address<input name="address"></label><label class="field">PAN<input name="pan"></label><button class="button">Save customer</button></form><form class="form-card" method="post"><h2>Create booking</h2><?=p4h('booking_add','bookings',$selectedProject)?><label class="field">Available unit<select name="unit_id"><?php foreach(array_filter($units,fn($u)=>in_array($u['status'],['available','hold','reserved'],true)) as $u):?><option value="<?=e($u['id'])?>"><?=e($u['unit_number'].' · '.$u['property_type'].' · '.inr($u['final_price']))?></option><?php endforeach;?></select></label><label class="field">Customer<select name="customer_id"><?php foreach($customers as $x):?><option value="<?=e($x['id'])?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label class="field">Lead<select name="lead_id"><option value="">Not linked</option><?php foreach($leads as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach;?></select></label><label class="field">Broker<select name="broker_id"><option value="">Direct sale</option><?php foreach($brokers as $b):?><option value="<?=e($b['id'])?>"><?=e($b['name'])?></option><?php endforeach;?></select></label><div class="form-grid"><label class="field">Discount<input type="number" name="discount"></label><label class="field">Booking amount<input type="number" name="booking_amount"></label></div><label class="field">Booking date<input type="date" name="booking_date" value="<?=date('Y-m-d')?>"></label><label class="field">Sales executive<select name="sales_executive_id"><option value="">Not assigned</option><?php foreach($users as $u):?><option value="<?=e($u['id'])?>"><?=e($u['name'])?></option><?php endforeach;?></select></label><label class="field">Payment plan<input name="payment_plan"></label><label class="field">Notes<input name="notes"></label><button class="button">Confirm booking</button></form></div><?=phase_table(['Customer','Project / unit','Final price','Booking amount','Broker','Status'],array_map(fn($b)=>[e($b['customer_name']).'<small>'.e($b['customer_phone']).'</small>',e($b['project_name'].' · '.$b['unit_number']),inr($b['final_price']),inr($b['booking_amount']),e($b['broker_name']?:'Direct'),'<span class="pill good">'.e($b['status']).'</span>'],$bookings))?>
<?php elseif($page==='collections'):?><section class="cards"><article class="card"><span>Total receivable</span><strong><?=inr($totalDue)?></strong></article><article class="card"><span>Collected</span><strong><?=inr($totalReceived)?></strong></article><article class="card"><span>Outstanding</span><strong><?=inr($totalDue-$totalReceived)?></strong></article><article class="card"><span>Overdue stages</span><strong><?=count(array_filter($schedules,fn($s)=>$s['status']==='overdue'))?></strong></article></section><div class="split"><form class="form-card" method="post"><h2>Add payment stage</h2><?=p4h('schedule_add','collections',$selectedProject)?><label class="field">Booking<select name="booking_id"><?php foreach($bookings as $b):?><option value="<?=e($b['id'])?>"><?=e($b['customer_name'].' · '.$b['unit_number'])?></option><?php endforeach;?></select></label><label class="field">Stage name<input name="stage_name" placeholder="10% within 15 days" required></label><label class="field">Due date<input type="date" name="due_date" required></label><label class="field">Amount due<input type="number" step=".01" name="amount_due" required></label><button class="button">Add stage</button></form><form class="form-card" method="post"><h2>Record collection</h2><?=p4h('payment_add','collections',$selectedProject)?><label class="field">Payment stage<select name="schedule_id"><?php foreach(array_filter($schedules,fn($s)=>$s['status']!=='paid') as $s):?><option value="<?=e($s['id'])?>"><?=e($s['customer_name'].' · '.$s['unit_number'].' · '.$s['stage_name'])?></option><?php endforeach;?></select></label><label class="field">Amount received<input type="number" step=".01" name="amount" required></label><label class="field">Payment date<input type="date" name="payment_date" value="<?=date('Y-m-d')?>"></label><label class="field">Method<input name="payment_method"></label><label class="field">Reference<input name="reference_no"></label><label class="field">Notes<input name="notes"></label><button class="button">Record payment</button></form></div><?=phase_table(['Customer / unit','Stage','Due date','Due','Received','Balance','Status'],array_map(fn($s)=>[e($s['customer_name'].' · '.$s['unit_number']),e($s['stage_name']),e($s['due_date']),inr($s['amount_due']),inr($s['amount_received']),inr((float)$s['amount_due']-(float)$s['amount_received']),'<span class="pill">'.e(str_replace('_',' ',$s['status'])).'</span>'],$schedules))?>
<?php else:?><form class="form-card wide" method="post"><h2>Add broker / channel partner</h2><?=p4h('broker_add','brokers',$selectedProject)?><div class="form-grid"><label class="field">Name<input name="name" required></label><label class="field">Company<input name="company_name"></label><label class="field">Phone<input name="phone"></label><label class="field">Email<input type="email" name="email"></label><label class="field">RERA number<input name="rera_number"></label><label class="field">Commission type<select name="commission_type"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label class="field">Commission value<input type="number" step=".01" name="commission_value"></label></div><button class="button">Save broker</button></form><?=phase_table(['Broker','Contact','RERA','Commission','Earned','Paid','Outstanding'],array_map(fn($b)=>[e($b['name']).'<small>'.e($b['company_name']).'</small>',e($b['phone']).'<small>'.e($b['email']).'</small>',e($b['rera_number']),e($b['commission_type']==='percentage'?$b['commission_value'].'%':inr($b['commission_value'])),inr($b['earned']),inr($b['paid']),inr((float)$b['earned']-(float)$b['paid'])],$brokers))?><?php endif;?>
